// DemoApp.js (or in your storybook)
import React, { useState } from 'react';
import Slider from './Slider';

export default function DemoReadOnlySlider() {
  const [value, setValue] = useState(50);
  return (
    <div style={{ padding: '2rem' }}>
      <h2>Read-only Slider Demo</h2>
      <p>Attempt to drag the thumb or edit the input below—even though it is "read-only."</p>
      <Slider
        labelText="Read-only Slider"
        min={0}
        max={100}
        step={1}
        value={value}
        readOnly
        onChange={({ value }) => setValue(value)}
      />
      <p>Current value (should stay at 50): {value}</p>
    </div>
  );
}

